mapper.select:
SELECT * FROM (
    SELECT metric_id, model_id, metric_time, latency_ms, throughput_qps, accuracy,
           success_rate, call_count, kb_hit_avg, metric_source, create_time
    FROM ai_model_metric
    WHERE model_id = #{modelId}
    ORDER BY metric_time DESC
    LIMIT #{limit}
) t ORDER BY t.metric_time ASC
